import React, { useState, useEffect } from "react";
import axios from "axios";

function BookingForm({ slot, onBooked }) {
  const [vehicleNumber, setVehicleNumber] = useState("");
  const [startTime, setStartTime] = useState("");
  const [endTime, setEndTime] = useState("");
  const [estimatedCost, setEstimatedCost] = useState(0);
  const [error, setError] = useState("");

  // Update cost when start or end time changes
  useEffect(() => {
    if (startTime && endTime) {
      const start = new Date(startTime);
      const end = new Date(endTime);

      if (end > start) {
        const diffMs = end - start;
        const diffHours = Math.ceil(diffMs / (1000 * 60 * 60));
        const rate = slot?.hourlyRate || 0;
        setEstimatedCost(diffHours * rate);
      } else {
        setEstimatedCost(0);
      }
    }
  }, [startTime, endTime, slot]);

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!slot) {
      setError("Slot not found.");
      return;
    }

    const start = new Date(startTime);
    const now = new Date();

    // Make sure start time is in the future
    if (start <= now) {
      setError("Start time cannot be in the past");
      return;
    }

    const end = new Date(endTime);
    if (end <= start) {
      setError("End time must be after start time");
      return;
    }

    const booking = {
      slotId: slot.id,
      vehicleNumber,
      startTime,
      endTime,
      estimatedCost,
    };

    try {
      const response = await axios.post("http://localhost:8080/api/bookings", booking);
      alert("Booking successful!");
      if (onBooked) onBooked(response.data);
    } catch (err) {
      console.error(err);
      setError("Failed to book slot.");
    }
  };

  if (!slot) {
    return <p>Loading slot...</p>;
  }

  return (
    <form onSubmit={handleSubmit}>
      <h2>Book Slot {slot.slotNumber}</h2>

      <div>
        <label>Vehicle Number:</label>
        <input
          type="text"
          value={vehicleNumber}
          onChange={(e) => setVehicleNumber(e.target.value)}
          required
        />
      </div>

      <div>
        <label>Start Time:</label>
        <input
          type="datetime-local"
          value={startTime}
          onChange={(e) => setStartTime(e.target.value)}
          required
        />
      </div>

      <div>
        <label>End Time:</label>
        <input
          type="datetime-local"
          value={endTime}
          onChange={(e) => setEndTime(e.target.value)}
          required
        />
      </div>

      <div>
        <p>Estimated Cost: ${estimatedCost.toFixed(2)}</p>
      </div>

      {error && <p style={{ color: "red" }}>{error}</p>}

      <button type="submit">Book</button>
    </form>
  );
}

export default BookingForm;
